 tx(s,m,f){return new Promise((ok,no)=>{const t=this.db.transaction(s,m),st=t.objectStore(s);const q=f(st);t.oncomplete=()=>ok(q&&q.result);t.onerror=()=>no(t.error)})},
 get(k){return this.tx('kv','readonly',s=>s.get(k))},put(k,v){return this.tx('kv','readwrite',s=>s.put(v,k))},
