V.home=()=>{const st=S.settings,ov=overall(),e=edgeList(),lg=leaguePts(wkStart(today())),nt=S.tests.filter(t=>daysTo(t.date)>=0).sort((a,b)=>a.date<b.date?-1:1)[0];
 const ks=[['students',AR(studentNames().length),'طالب'],['radar',PC(ov),'متوسط الإتقان'],['edge',AR(e.length),'طالب على الحافة'],['nafs',AR(S.questions.length),'سؤال في البنك'],['league',lg[0]&&lg[0][1]?esc(lg[0][0]):'—','متصدر الدوري هذا الأسبوع'],['ops',nt?AR(daysTo(nt.date))+' يوم':'—',nt?'حتى '+esc(nt.name):'لا يوجد اختبار محدد'],['visits',AR(S.visits.length),'زيارة صفية'],['practices',AR(S.practices.length),'ممارسة متميزة']];
 const sk=skillNames().map(s=>[s,skillAvg(s)]).filter(x=>x[1]!=null).sort((a,b)=>a[1]-b[1]).slice(0,6);
 const A=allowed();const Q=[['results','📡','نتيجة اختبار قصير','radar'],['bulkR','📋','درجات فصل كامل','radar'],['students','🧑‍🎓','طالب جديد','students'],['points','🏆','نقاط للدوري','league'],['reflections','🪞','تأمل بعد الدرس','mirror'],['visits','🔬','زيارة صفية','visits'],['pacts','🤝','ميثاق أسبوعي','pact'],['practices','🌟','ممارسة متميزة','practices'],['ch','🧠','بدء تحدي ٥ دقائق','nafs']].filter(q=>A.includes(q[3]));
 return`<div class="hero"><h2>منصة إتقان لتحسين نواتج التعلم</h2><p>${st.school?esc(st.school)+' · ':''}${esc(HF.format(new Date()))}${st.user.name?' · مرحباً '+esc(st.user.name):''}</p><p class="gold small">قياس دقيق · تدخل مبكر · تحفيز مستمر — والبيانات على جهازك فقط 🔒</p></div>
 ${!st.started?startCard():''}
 <div class="card"><h3>⚡ إدخال سريع</h3><div class="quick">${Q.map(q=>`<button data-act="quick" data-q="${q[0]}"><span class="e">${q[1]}</span>${q[2]}</button>`).join('')}<button data-act="quickVoice"><span class="e">🎤</span>إدخال صوتي سريع</button></div></div>
 <div class="grid g4">${ks.filter(k=>A.includes(k[0])).map(k=>`<a class="kpi" href="#${k[0]}"><b>${k[1]}</b><span>${k[2]}</span></a>`).join('')}</div>
 <div class="grid g2" style="margin-top:14px"><div class="card"><h3>📉 أضعف المهارات (متوسط الإتقان)</h3>${barChart(sk,{col:heatCol,label:'أضعف المهارات'})}</div><div class="card"><h3>🏆 ترتيب الفصول هذا الأسبوع</h3>${barChart(lg.slice(0,6).filter(x=>x[1]>0),{pct:false,label:'الدوري'})}</div>
 <div class="card"><h3>🪞 نسبة الفهم بعد الدروس</h3>${lineChart(trendBy(S.reflections,'understood'),{label:'الفهم'})}</div><div class="card"><h3>📡 متوسط نتائج الاختبارات القصيرة</h3>${lineChart(trendBy(S.results,'score'),{c:'#0d9488',label:'النتائج'})}</div></div>
 ${creditHtml()}`};
function creditHtml(){return`<div class="credit"><span class="cr-t">فكرة وتصميم</span><span class="cr-r">عضو الفريق التنفيذي بمحافظة الدوادمي – قطاع السر</span><span class="cr-n">عبدالله خالد العتيبي</span><a href="https://wa.me/966504153442" target="_blank" rel="noopener">${WAICON}<span>للتواصل: 0504153442</span></a></div>`}
const WAICON='<svg class="wa" viewBox="0 0 32 32" aria-hidden="true"><path fill="#25D366" d="M16 2.9A13 13 0 0 0 4.8 22.6L3 29l6.6-1.7A13 13 0 1 0 16 2.9z"/><path fill="#fff" d="M23.3 19.4c-.4-.2-2.3-1.1-2.6-1.3-.4-.1-.6-.2-.9.2l-1.2 1.5c-.2.2-.4.3-.8.1a10.6 10.6 0 0 1-5.3-4.6c-.4-.7.4-.6 1.1-2.1.1-.3 0-.5 0-.7l-1.2-2.8c-.3-.7-.6-.6-.9-.6h-.7a1.4 1.4 0 0 0-1 .5 4.3 4.3 0 0 0-1.3 3.1 7.4 7.4 0 0 0 1.6 4c.2.2 2.7 4.2 6.6 5.9 2.5 1.1 3.4 1.2 4.7 1 .8-.1 2.3-1 2.7-1.9s.3-1.7.2-1.9c-.1-.2-.4-.3-.8-.4z"/></svg>';
function startCard(){const st=S.settings;const steps=[[!!st.role,'اختر دورك (مدير، وكيل، معلم، مرشد…) لتظهر الأقسام المناسبة فقط','settings'],[!!st.school,'أدخل اسم المدرسة ونوعها (بنين/بنات) وبياناتك','settings'],[S.settings.lists.classes.length>0,'أضف فصولك وموادك (قوائم قابلة للتعديل)','settings'],[S.students.length>0,'أضف الطلاب يدوياً أو من Excel أو بالصوت','students'],[S.results.length>0||S.marks.length>0,'أدخل أول نتائج — وستعمل بقية الأقسام تلقائياً','radar']];
 return`<div class="card"><h3>🚀 ابدأ في ٥ خطوات</h3>${!st.role?`<div class="acts" style="margin-bottom:10px">${Object.entries(ROLES).map(([k,v])=>`<button class="btn ${k==='teacher'?'':'ghost'} sm" data-act="setRole" data-r="${k}">${esc(v[0])}</button>`).join('')}</div>`:''}<ol class="steps">${steps.map(s=>`<li class="${s[0]?'done':''}"><a href="#${s[2]}">${esc(s[1])}</a></li>`).join('')}</ol><div class="acts"><button class="btn ghost sm" data-act="loadSample">🧪 تحميل بيانات تجريبية للتجربة</button><button class="btn ghost sm" data-act="hideStart">إخفاء هذه البطاقة</button></div></div>`}

V.students=()=>head('🧑‍🎓 الطلاب وأولياء الأمور','قائمة الطلاب أساس كل الأقسام. جوال ولي الأمر يُستخدم لرسائل واتساب فقط بضغطك.')+tip('يمكنك استيراد كشف نور مباشرة: اختر الملف ثم طابِق أعمدة «اسم الطالب» و«الفصل» و«الجوال». تُضاف الفصول الجديدة للقوائم تلقائياً.')+tbl('students');
/* V.skills → skills.js */

V.radar=()=>{const s=VS.radar,cls=s.cls,sks=skillNames(),sts=studentNames(cls);let body='';
 if(s.tab==='heat'){body=!S.results.length&&!S.attempts.length?tbl('results',{bulk:1,emptyMsg:'أدخل نتائج الاختبارات القصيرة لكل طالب في كل مهارة لتظهر الخريطة الحرارية.'}):
  `<div class="card"><h3>🌡️ الخريطة الحرارية (الطالب × المهارة)</h3><div class="acts small" style="margin-bottom:8px">${[['#fca5a5','أقل من ٥٠'],['#fdba74','٥٠–٦٤'],['#fde68a','٦٥–'+AR(TH().m-1)],['#86efac',AR(TH().m)+'–٨٩'],['#4ade80','٩٠+']].map(x=>`<span class="tag" style="background:${x[0]};color:#111">${x[1]}</span>`).join('')}</div><div class="tw"><table class="heat"><thead><tr><th>الطالب</th>${sks.map(k=>`<th title="${esc(k)}" style="white-space:normal;min-width:110px">${esc(shortSk(k))}</th>`).join('')}<th>المتوسط</th></tr></thead><tbody>
  ${sts.map(st=>{const ms=sks.map(k=>mastery(st,k));return`<tr><td>${esc(st)}</td>${ms.map(m=>`<td class="h" style="background:${heatCol(m)}">${m==null?'':AR(m)}</td>`).join('')}<td class="h"><b>${AR(avg(ms))}</b></td></tr>`}).join('')}
  <tr><td><b>متوسط المهارة</b></td>${sks.map(k=>{const m=skillAvg(k,cls);return`<td class="h" style="background:${heatCol(m)}"><b>${AR(m)}</b></td>`}).join('')}<td></td></tr></tbody></table></div></div>`}
 else if(s.tab==='groups'){const G=sks.map(k=>({k,g:groups(k,cls),m:skillAvg(k,cls)})).filter(x=>x.m!=null).sort((a,b)=>a.m-b.m);
  body=G.length?G.map(({k,g,m})=>`<div class="card"><h3>🎯 ${esc(k)} <span class="tag" style="background:${heatCol(m)};color:#111">متوسط ${PC(m)}</span></h3><div class="grid g3">${[['low','🔴 مجموعة علاجية (أقل من ٦٠٪)','bad'],['mid','🟡 مجموعة تعزيز','warn'],['high','🟢 مجموعة إثراء (متقن)','ok']].map(([gk,t,c])=>`<div><b class="tag ${c}">${t} · ${AR(g[gk].length)}</b><p class="small">${g[gk].map(x=>esc(x.st)+' ('+AR(x.m)+')').join('، ')||'<span class="muted">لا أحد</span>'}</p>${g[gk].length?`<ul class="small">${ACTV[gk].slice(0,3).map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`:''}</div>`).join('')}</div></div>`).join(''):`<div class="card empty">لا توجد نتائج بعد لتكوين المجموعات. <button class="btn sm" data-act="tab" data-m="radar" data-t="res">إدخال النتائج</button></div>`}
 else body=tbl('results',{bulk:1});
 return head('📡 رادار الفاقد التعليمي','حدّد مواضع الفاقد لكل مهارة ولكل طالب، واحصل على مجموعات علاجية مقترحة.',clsSel('radarCls',cls))+tabs('radar',s.tab,[['heat','🌡️ الخريطة الحرارية'],['groups','👥 المجموعات العلاجية'],['res','📝 النتائج والإدخال']])+tip('الإتقان = متوسط درجات المهارة (ويُدمج معه أداء الطالب في تحدي نافس). حد الإتقان الحالي '+PC(TH().m)+' ويمكن تعديله من الإعدادات.')+body};

V.edge=()=>{const L=edgeList(),p=L.filter(x=>x.type==='pass'),e=L.filter(x=>x.type==='exc');
 const row=x=>`<tr><td>${esc(x.st)}</td><td>${esc(x.subject)}</td><td>${AR(x.grade)}</td><td>${x.ab==null?'—':AR(x.ab)}</td><td>${x.pt==null?'—':PC(x.pt)}</td><td><b>${AR(x.pred)}</b></td><td>${x.risk?'<span class="tag bad">عامل خطر</span>':''}</td><td class="acts"><button class="btn sm" data-act="plan" data-st="${esc(x.st)}" data-sub="${esc(x.subject)}">📅 خطة أسبوعين</button></td></tr>`;
 const t=(L,ttl,c)=>`<div class="card"><h3>${ttl} <span class="tag ${c}">${AR(L.length)}</span></h3>${L.length?`<div class="tw"><table><tr><th>الطالب</th><th>المادة</th><th>الدرجة</th><th>الغياب</th><th>المشاركة</th><th>المتوقع</th><th></th><th class="acts"></th></tr>${L.map(row).join('')}</table></div>`:'<p class="muted">لا يوجد طلاب في هذه الفئة حالياً.</p>'}</div>`;
 return head('⚖️ الطلاب على الحافة','تنبؤ بالطلاب القريبين من النجاح أو التميز اعتماداً على الدرجة والغياب والمشاركة.')+tip(`الدرجة المتوقعة = الدرجة − (الغياب × ٠٫٨) + أثر المشاركة. «حافة النجاح»: متوقع بين ${AR(TH().p-15)} و${AR(TH().p+10)}. «حافة التميز»: قريب من ${AR(TH().e)}. ${S.marks.length?'':'<b>لا توجد درجات بعد — تُستخدم نتائج الاختبارات القصيرة إن وُجدت.</b>'}`)
 +`<div class="grid g2">${t(p,'🟠 على حافة النجاح','warn')}${t(e,'🔵 على حافة التميز','info')}</div>`+tbl('marks',{bulk:1})};
function planDlg(st,sub){const x=edgeList().find(e=>e.st===st&&e.subject===sub);if(!x)return;const P=plan2w(x);
 dlg(`<div id="planDoc"><h3>📅 خطة دعم لمدة أسبوعين — ${esc(st)}</h3><p class="small">${esc(sub)} · الدرجة ${AR(x.grade)} · المتوقع ${AR(x.pred)} · الفئة: ${x.type==='pass'?'حافة النجاح':'حافة التميز'} · ${esc(HF.format(new Date()))}</p><div class="tw"><table><tr><th>اليوم</th><th>الإجراء</th><th>✓</th></tr>${P.map(d=>`<tr><td>${d.lbl}</td><td>${esc(d.act)}</td><td>☐</td></tr>`).join('')}</table></div><p class="small"><b>مؤشر النجاح:</b> ${x.type==='pass'?'تجاوز درجة '+AR(TH().p+10):'بلوغ '+AR(TH().e)+' فأكثر'} في اختبار قصير نهاية الأسبوع الثاني.</p></div>
 <div class="dlg-acts"><button type="button" class="btn" data-act="docPdf" data-el="planDoc" data-name="خطة-${esc(st)}">📄 PDF</button><button type="button" class="btn ghost" data-act="pactFromPlan" data-st="${esc(st)}" data-sub="${esc(sub)}">🤝 إرسال لولي الأمر كميثاق</button><button class="btn ghost" value="c">إغلاق</button></div>`)}

/* ---------- تدرّب على النماذج الرسمية (نماذج التهيئة ٢٠٢٦) ---------- */
let OQ=null,PR=null,PRS={g:'',s:'',m:'',st:'',t:false};
function oqLoad(){if(OQ)return;OQ='loading';fetch('nafs-official/questions.json').then(r=>r.json()).then(d=>{OQ=d;render()}).catch(()=>{OQ=null;toast('تعذّر تحميل أسئلة النماذج الرسمية — تحقّق من الاتصال')})}
const OG=['الثالث الابتدائي','السادس الابتدائي','الثالث المتوسط'];
function pracView(){if(!Array.isArray(OQ)){oqLoad();return`<div class="card"><p class="muted">⏳ جارٍ تحميل أسئلة النماذج الرسمية…</p></div>`}
 if(PR)return PR.done?pracDone():pracQ();
 const subs=[...new Set(OQ.filter(q=>!PRS.g||q.grade===PRS.g).map(q=>q.subject))];if(PRS.s&&!subs.includes(PRS.s))PRS.s='';
 const pool=pracPool(),stud=S.settings.role==='student';
 const mine=(S.offPrac||[]).slice(-200).reverse();
 return `<div class="card chal" style="text-align:right"><h3 style="text-align:center">🎯 تدرّب على النماذج الرسمية</h3><p class="muted" style="text-align:center">أسئلة نماذج التهيئة الرسمية لاختبارات نافس ٢٠٢٦ كما وردت في ملفات هيئة تقويم التعليم والتدريب (صور مقتطعة من الملف الأصلي) مع الإجابة من مفتاح الإجابة الرسمي.</p>
 <div class="fgrid"><label class="f">الصف<select id="prG"><option value="">اختر الصف</option>${OG.map(g=>`<option ${PRS.g===g?'selected':''}>${g}</option>`).join('')}</select></label>
 <label class="f">المادة<select id="prS"><option value="">كل المواد (مختلط)</option>${subs.map(s=>`<option ${PRS.s===s?'selected':''}>${s}</option>`).join('')}</select></label>
 <label class="f">النموذج<select id="prM"><option value="">النموذجان (مختلط)</option>${['أ','ب'].map(m=>`<option value="${m}" ${PRS.m===m?'selected':''}>نموذج (${m})</option>`).join('')}</select></label>
 <label class="f">اسم الطالب (اختياري)<input id="prSt" list="prStL" autocomplete="off" value="${esc(PRS.st)}"><datalist id="prStL">${studentNames().map(n=>`<option value="${esc(n)}">`).join('')}</datalist></label></div>
 <label style="display:flex;gap:.5rem;align-items:center;margin:.6rem 0"><input type="checkbox" id="prT" ${PRS.t?'checked':''}> ⏱️ مؤقّت (دقيقتان لكل سؤال تقريبًا كما في زمن النموذج)</label>
 <p style="text-align:center"><button class="btn" data-act="prStart" ${PRS.g?'':'disabled'}>▶️ ابدأ التدريب (${AR(pool.length)} سؤالًا)</button></p>
 <p class="muted" style="font-size:.85rem;text-align:center">المصدر: نموذج التهيئة ٢٠٢٦ – هيئة تقويم التعليم والتدريب. تُحفظ النتائج على هذا الجهاز فقط.</p></div>
 ${mine.length?`<div class="card"><h3>📊 ${stud?'نتائجي السابقة':'نتائج التدريب على النماذج الرسمية (على هذا الجهاز)'}</h3><div class="tw"><table><tr><th>الطالب</th><th>الصف</th><th>المادة</th><th>النموذج</th><th>النتيجة</th><th>التاريخ</th></tr>${mine.map(r=>`<tr><td>${esc(r.student||'—')}</td><td>${esc(r.grade)}</td><td>${esc(r.subject||'مختلط')}</td><td>${r.model?'('+r.model+')':'مختلط'}</td><td>${AR(r.ok)} / ${AR(r.n)} (${PC(100*r.ok/r.n)})</td><td>${esc(r.date)}</td></tr>`).join('')}</table></div>${stud?'':`<button class="btn ghost sm no-print" data-act="prClear">مسح نتائج التدريب</button>`}</div>`:''}`}
function pracPool(){return Array.isArray(OQ)?OQ.filter(q=>q.grade===PRS.g&&(!PRS.s||q.subject===PRS.s)&&(!PRS.m||q.model===PRS.m)):[]}
function prRead(){const g=$('#prG');if(!g)return;PRS.g=g.value;PRS.s=$('#prS').value;PRS.m=$('#prM').value;PRS.st=($('#prSt').value||'').trim();PRS.t=$('#prT').checked}
function prStart(){prRead();const L=pracPool();if(!L.length){toast('اختر الصف أولًا');return}
 const sorted=L.slice().sort((a,b)=>a.model.localeCompare(b.model)||OGS(a.subject)-OGS(b.subject)||a.n-b.n);
 PR={L:sorted,i:0,ans:{},end:PRS.t?Date.now()+sorted.length*120e3:0,done:false};render();prTick()}
const OGS=s=>['الرياضيات','العلوم','القراءة'].indexOf(s);
function prTick(){if(!PR||!PR.end||PR.done)return;const el=$('#prTm');const left=PR.end-Date.now();if(left<=0){prFinish();return}if(el)el.textContent=fmtT(left);setTimeout(prTick,1000)}
function pracQ(){const q=PR.L[PR.i],a=PR.ans[q.id],al=['أ','ب','ج','د'];
 return `<div class="card chal"><div class="acts" style="justify-content:space-between;flex-wrap:wrap"><span>السؤال ${AR(PR.i+1)} من ${AR(PR.L.length)}</span>${PR.end?`<span class="timer" id="prTm">${fmtT(PR.end-Date.now())}</span>`:''}<span>✓ ${AR(Object.keys(PR.ans).filter(k=>PR.ans[k].ok).length)}</span></div>
 <p class="muted" style="font-size:.85rem">${esc(q.grade)} · ${esc(q.subject)} · نموذج (${q.model}) · السؤال رقم ${AR(q.n)}<br>${esc(q.src)}</p>
 ${q.passage?`<details ${PR.i===0||PR.L[PR.i-1].passage!==q.passage?'open':''} style="text-align:right;margin:.5rem 0"><summary style="cursor:pointer;font-weight:700">📖 نص القراءة (اضغط للإظهار/الإخفاء)</summary><a href="${q.passage}" target="_blank" rel="noopener" title="تكبير"><img src="${q.passage}" alt="نص القراءة من النموذج الرسمي" style="width:100%;border-radius:12px;margin-top:.5rem;background:#fff"></a><span class="muted" style="font-size:.8rem">اضغط على الصورة لتكبيرها</span></details>`:''}
 <a href="${q.img}" target="_blank" rel="noopener" title="تكبير"><img src="${q.img}" alt="السؤال ${q.n} من النموذج الرسمي" style="width:100%;border-radius:12px;background:#fff;border:1px solid var(--line)"></a>
 <p class="muted" style="margin:.5rem 0">اختر الإجابة الصحيحة:</p>
 <div class="opts" style="grid-template-columns:repeat(4,1fr)">${al.map(x=>`<button data-act="prAns" data-a="${x}" class="${a?(x===q.ans?'ok':a.c===x?'no':''):''}" ${a?'disabled':''}>${x}</button>`).join('')}</div>
 ${a?`<p style="font-weight:800;margin-top:.6rem">${a.ok?'✅ إجابة صحيحة':'❌ إجابة غير صحيحة — الصحيحة: ('+q.ans+')'}</p><p><button class="btn" data-act="prNext">${PR.i+1<PR.L.length?'التالي ⬅️':'🏁 عرض النتيجة'}</button></p>`:''}
 <p><button class="btn ghost sm" data-act="prStop">إنهاء التدريب</button></p></div>`}
function prAns(x){const q=PR.L[PR.i];if(PR.ans[q.id])return;PR.ans[q.id]={c:x,ok:x===q.ans};render()}
function prNext(){if(PR.i+1<PR.L.length){PR.i++;render();scrollTo(0,0)}else prFinish()}
function prFinish(){if(!PR||PR.done)return;PR.done=true;const n=Object.keys(PR.ans).length;
 if(n){const ok=Object.values(PR.ans).filter(a=>a.ok).length;S.offPrac=S.offPrac||[];S.offPrac.push({id:uid(),student:PRS.st,grade:PRS.g,subject:PRS.s,model:PRS.m,n,ok,date:today(),wrong:PR.L.filter(q=>PR.ans[q.id]&&!PR.ans[q.id].ok).map(q=>q.id)});save()}
 render();scrollTo(0,0)}
function pracDone(){const n=Object.keys(PR.ans).length,ok=Object.values(PR.ans).filter(a=>a.ok).length,W=PR.L.filter(q=>PR.ans[q.id]&&!PR.ans[q.id].ok);
 return `<div class="card chal"><h3>🏁 النتيجة</h3><div class="q">${AR(ok)} من ${AR(n)} ${n?'('+PC(100*ok/n)+')':''}</div>${n<PR.L.length?`<p class="muted">أُجيب عن ${AR(n)} من ${AR(PR.L.length)} سؤالًا.</p>`:''}
 <p><button class="btn" data-act="prAgain">🔁 تدريب جديد</button></p></div>
 ${W.length?`<div class="card"><h3>🔍 مراجعة الأخطاء (${AR(W.length)})</h3>${W.map(q=>`<div style="border-top:1px solid var(--line);padding:.6rem 0"><p class="muted" style="font-size:.85rem">${esc(q.subject)} · نموذج (${q.model}) · السؤال ${AR(q.n)}</p>${q.passage?`<details><summary>📖 نص القراءة</summary><img src="${q.passage}" alt="" style="width:100%;background:#fff;border-radius:10px"></details>`:''}<img src="${q.img}" alt="" style="width:100%;background:#fff;border-radius:10px;border:1px solid var(--line)"><p>إجابتك: <b style="color:#b91c1c">(${PR.ans[q.id].c})</b> · الإجابة الصحيحة: <b style="color:#15803d">(${q.ans})</b></p></div>`).join('')}</div>`:n?'<div class="card"><p>🌟 ممتاز! لا توجد أخطاء.</p></div>':''}`}
/* ---------- نافس الذكي ---------- */
function nafsOfficial(){const M='https://media.etec.gov.sa/media/',G=[['الصف الثالث الابتدائي','القراءة، الرياضيات',[['أ','xrsnq2oo/preparation-form-a-3rdgrade-ar.pdf'],['ب','e0mdmekl/preparation-form-b-3rdgrade-ar.pdf']]],['الصف السادس الابتدائي','القراءة، الرياضيات، العلوم',[['أ','j2pgnt0a/preparation-form-a-6thgrade-ar.pdf'],['ب','y5tljfa2/preparation-form-b-6thgrade-ar.pdf']]],['الصف الثالث المتوسط','القراءة، الرياضيات، العلوم',[['أ','zhpbzrhn/preparation-form-a-9thgrade-ar.pdf'],['ب','yn3l35gc/preparation-form-b-9thgrade-ar.pdf']]]];
 const L=(h,t)=>`<a class="btn ghost sm" href="${h}" target="_blank" rel="noopener noreferrer">${t}</a>`;
 return `<div class="card"><h3>📘 نماذج التهيئة الرسمية – هيئة تقويم التعليم والتدريب</h3><p class="muted">نماذج تهيئة رسمية لاختبارات نافس 2026 مع مفاتيح الإجابة، تُفتح من موقع الهيئة مباشرة.</p><div class="grid g2">${G.map(g=>`<div class="card"><h4>${g[0]}</h4><p class="muted">المواد: ${g[1]}</p><div style="display:flex;flex-wrap:wrap;gap:.5rem">${g[2].map(m=>L(M+m[1],'📄 فتح نموذج ('+m[0]+')')).join('')}</div></div>`).join('')}</div><h4>روابط رسمية</h4><div style="display:flex;flex-wrap:wrap;gap:.5rem">${L('https://nafs.etec.gov.sa/','🎯 موقع نواتج التعلم المستهدفة')}${L(M+'sszdnh2h/نواتج-التعلم-2026.pdf','📑 نواتج التعلم 2026')}${L(M+'ys1mstka/دليل-المدرسة-الإرشادي-لاختبارات-نافس-الوطنية.pdf','🏫 دليل المدرسة الإرشادي')}${L(M+'e2dhyiyq/دليل-ولي-الأمر-اختبارات-نافس.pdf','👪 دليل ولي الأمر')}${L(M+'pkdlx5uz/دليل-الطالب-الإرشادي-لاختبارات-نافس.pdf','🧑‍🎓 دليل الطالب')}${L('https://etec.gov.sa/ar/programs/nafs','🔗 صفحة نافس')}</div><p class="muted" style="margin-top:.6rem">المصدر: هيئة تقويم التعليم والتدريب</p></div>`}
let CH=null;const LV=['سهل','متوسط','صعب'];
V.nafs=()=>{const s=VS.nafs;const stud=S.settings.role==='student';if(stud&&!['ch','prac','off'].includes(s.tab))s.tab='ch';let body='';
 if(s.tab==='ch')body=CH?chView():`<div class="card chal"><h3>🧠 تحدي الخمس دقائق اليومي</h3><p class="muted">أسئلة متكيفة: تصعب عند الإجابة الصحيحة وتسهل عند الخطأ.</p>${S.questions.length?`<div class="fgrid" style="text-align:right"><label class="f">اسم الطالب<input id="chSt" list="chStL" autocomplete="off"><datalist id="chStL">${studentNames().map(n=>`<option value="${esc(n)}">`).join('')}</datalist></label><label class="f">المادة<select id="chSub"><option value="">كل المواد</option>${[...new Set(S.questions.map(q=>q.subject).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><button class="btn gold" style="margin-top:12px;font-size:1.1rem" data-act="chStart">▶️ ابدأ التحدي</button>`:`<div class="empty">بنك الأسئلة فارغ. ${stud?'اطلب من معلمك إضافة الأسئلة.':`<button class="btn sm" data-act="tab" data-m="nafs" data-t="bank">إضافة أسئلة</button> <button class="btn ghost sm" data-act="seedQ">إضافة ٣ أسئلة نموذجية عامة</button>`}</div>`}</div>`;
 else if(s.tab==='bank')body=tip('اربط كل سؤال بناتج تعلّم ومستوى صعوبة. القالب الفارغ يحوي أعمدة: المادة، الصف، ناتج التعلم، السؤال، الخيارات، الإجابة (أ/ب/ج/د)، المستوى.')+(S.questions.length?'':`<p><button class="btn ghost sm" data-act="seedQ">إضافة ٣ أسئلة نموذجية عامة (للتجربة)</button></p>`)+tbl('questions');
 else if(s.tab==='off')body=nafsOfficial();
 else if(s.tab==='prac')body=pracView();
 else{const sk=[...new Set(S.attempts.map(a=>a.skill||'غير مصنف'))].map(k=>{const L=S.attempts.filter(a=>(a.skill||'غير مصنف')===k);return[k,100*L.filter(a=>a.ok).length/L.length,L.length]}).sort((a,b)=>a[1]-b[1]);
  const st=[...new Set(S.attempts.map(a=>a.student))].map(n=>{const L=S.attempts.filter(a=>a.student===n);return[n,100*L.filter(a=>a.ok).length/L.length,L.length,Math.max(...L.map(a=>a.lv||1))]});
  body=`<div class="grid g2"><div class="card"><h3>🎯 الإتقان حسب ناتج التعلم</h3>${barChart(sk.map(x=>[x[0],x[1]]),{col:heatCol})}</div><div class="card"><h3>🧑‍🎓 أداء الطلاب في التحدي</h3>${st.length?`<div class="tw"><table><tr><th>الطالب</th><th>الدقة</th><th>عدد الأسئلة</th><th>أعلى مستوى</th></tr>${st.map(x=>`<tr><td>${esc(x[0])}</td><td>${PC(x[1])}</td><td>${AR(x[2])}</td><td>${LV[x[3]-1]||''}</td></tr>`).join('')}</table></div>`:'<p class="muted">لم تُسجَّل محاولات بعد. ابدأ تحدياً من تبويب «التحدي اليومي».</p>'}</div></div>${S.attempts.length?`<button class="btn ghost sm no-print" data-act="clearAtt">مسح سجل المحاولات</button>`:''}`}
 return head('🧠 نافس الذكي','بنك أسئلة حسب نواتج التعلم + تحدٍ يومي متكيف على الجهاز + تقرير إتقان.')+tabs('nafs',s.tab,stud?[['ch','▶️ التحدي اليومي'],['prac','🎯 تدرّب على النماذج الرسمية'],['off','📘 نماذج التهيئة الرسمية']]:[['ch','▶️ التحدي اليومي'],['prac','🎯 تدرّب على النماذج الرسمية'],['bank','📚 بنك الأسئلة'],['rep','📊 تقرير الإتقان'],['off','📘 نماذج التهيئة الرسمية']])+body};
function seedQ(){mut(()=>{[{subject:'الرياضيات',skill:'الجمع (مثال عام)',q:'ناتج ٧ + ٥ = ؟',a:'١١',b:'١٢',c:'١٣',d:'١٠',ans:'ب',level:'سهل'},{subject:'الرياضيات',skill:'الضرب (مثال عام)',q:'ناتج ٦ × ٨ = ؟',a:'٤٢',b:'٥٦',c:'٤٨',d:'٥٤',ans:'ج',level:'متوسط'},{subject:'العلوم',skill:'حالات المادة (مثال عام)',q:'تتحول المادة من الصلبة إلى السائلة بعملية:',a:'التبخر',b:'التكاثف',c:'الانصهار',d:'التجمد',ans:'ج',level:'سهل'}].forEach(q=>{ensureRefs(q,C.questions.f);S.questions.push({id:uid(),grade:'',...q})})},'✓ أُضيفت أسئلة نموذجية عامة')}
function chStart(){const st=($('#chSt').value||'').trim();if(!st){toast('اكتب اسم الطالب');$('#chSt').focus();return}const sub=$('#chSub').value;const pool=S.questions.filter(q=>!sub||q.subject===sub);if(!pool.length){toast('لا أسئلة لهذه المادة');return}
 CH={st,sub,lv:2,end:Date.now()+5*60e3,n:0,ok:0,asked:[],q:null,ans:null};nextQ();render();tick()}
function nextQ(){const pool=S.questions.filter(q=>!CH.sub||q.subject===CH.sub);const lvOf=q=>Math.max(1,LV.indexOf(q.level)+1||2);let cand=pool.filter(q=>!CH.asked.includes(q.id));if(!cand.length){CH.asked=[];cand=pool}
 cand.sort((a,b)=>Math.abs(lvOf(a)-CH.lv)-Math.abs(lvOf(b)-CH.lv)||Math.random()-.5);CH.q=cand[0];CH.asked.push(CH.q.id);CH.ans=null}
function chView(){const left=Math.max(0,CH.end-Date.now());if(!left||!CH.q)return chDone();const q=CH.q,ks=['a','b','c','d'].filter(k=>q[k]);const al=['أ','ب','ج','د'];
 return`<div class="card chal"><div class="acts" style="justify-content:space-between"><span>👤 ${esc(CH.st)}</span><span class="timer" id="chT">${fmtT(left)}</span><span>✓ ${AR(CH.ok)} من ${AR(CH.n)} · المستوى: ${LV[CH.lv-1]}</span></div><div class="q">${esc(q.q)}</div><div class="opts">${ks.map((k,i)=>`<button data-act="chAns" data-a="${al[i]}" class="${CH.ans?(al[i]===q.ans?'ok':CH.ans===al[i]?'no':''):''}" ${CH.ans?'disabled':''}>${al[i]}) ${esc(q[k])}</button>`).join('')}</div>${CH.ans?`<p><button class="btn" data-act="chNext">التالي ⬅️</button></p>`:''}<p><button class="btn ghost sm" data-act="chStop">إنهاء التحدي</button></p></div>`}
const fmtT=ms=>{const s=Math.ceil(ms/1000);return AR(Math.floor(s/60))+':'+String(s%60).padStart(2,'0').replace(/\d/g,d=>'٠١٢٣٤٥٦٧٨٩'[d])};
function tick(){if(!CH)return;const e=$('#chT');const left=CH.end-Date.now();if(left<=0){render();return}if(e)e.textContent=fmtT(left);setTimeout(tick,500)}
function chAns(a){const q=CH.q;const ok=a===q.ans;CH.ans=a;CH.n++;if(ok)CH.ok++;CH.lv=Math.max(1,Math.min(3,CH.lv+(ok?1:-1)));S.attempts.push({id:uid(),student:CH.st,skill:q.skill||'',subject:q.subject||'',ok,lv:Math.max(1,LV.indexOf(q.level)+1||2),date:today()});save();render()}
function chDone(){const r=CH;const p=r.n?100*r.ok/r.n:0;return`<div class="card chal"><h3>🎉 أحسنت يا ${esc(r.st)}!</h3><div class="timer">${AR(r.ok)} / ${AR(r.n)}</div><p>دقة ${PC(p)} · وصلت للمستوى: ${LV[r.lv-1]} · أُضيفت ${AR(r.ok)} نقطة لفصلك في الدوري 🏆</p><button class="btn gold" data-act="chReset">تحدٍّ جديد</button></div>`}

/* ---------- league ---------- */
V.league=()=>{const wk=VS.league.wk||wkStart(today());const L=leaguePts(wk);const max=Math.max(1,...L.map(x=>x[1]));
 const tops={};const s=wk,e=iso(new Date(pd(wk).getTime()+7*864e5));S.attempts.filter(a=>a.ok&&a.date>=s&&a.date<e).forEach(a=>tops[a.student]=(tops[a.student]||0)+1);S.results.filter(r=>r.date>=s&&r.date<e&&r.score>=TH().m).forEach(r=>tops[r.student]=(tops[r.student]||0)+2);
 const TS=Object.entries(tops).sort((a,b)=>b[1]-a[1]).slice(0,10);
 const rank=`<div class="league">${L.length?L.map((x,i)=>`<div class="row ${i===0&&x[1]?'r1':''}"><span class="rk">${i<3&&x[1]?['🥇','🥈','🥉'][i]:AR(i+1)}</span><b style="min-width:110px">${esc(x[0])}</b><div class="bar"><i style="width:${100*x[1]/max}%"></i></div><b>${AR(x[1])}</b></div>`).join(''):'<div class="empty">أضف الفصول من الإعدادات أو سجّل نقاطاً ليظهر الترتيب.</div>'}</div>`;
 return head('🏆 دوري الفصول','نقاط الإتقان الأسبوعية: ٢ لكل مهارة متقنة في الاختبارات القصيرة، ١ لكل إجابة صحيحة في نافس، + نقاط يدوية.',`<button class="btn ghost sm" data-act="wk" data-d="-7">→ السابق</button><span class="tag">أسبوع ${esc(hijS(wk))}</span><button class="btn ghost sm" data-act="wk" data-d="7">التالي ←</button><button class="btn gold sm" data-act="display">📺 وضع شاشة العرض</button>`)
 +`<div class="grid g2"><div class="card"><h3>📊 ترتيب الفصول</h3>${rank}</div><div class="card"><h3>🎖️ لوحة الشرف — نجوم الأسبوع</h3>${TS.length?`<ol>${TS.map(x=>`<li><b>${esc(x[0])}</b> <span class="muted small">${esc(clsOf(x[0]))}</span> — ${AR(x[1])} نقطة</li>`).join('')}</ol>`:'<p class="muted">تظهر هنا أسماء الطلاب الأعلى نقاطاً هذا الأسبوع.</p>'}${L[0]&&L[0][1]?`<button class="btn ghost sm no-print" data-act="certLeague" data-c="${esc(L[0][0])}">🏅 شهادة بطل الدوري لطلاب ${esc(L[0][0])}</button>`:''}</div></div>`+tbl('points',{title:'النقاط اليدوية (سلوك، مبادرات، واجبات)'})};
function displayMode(){const wk=VS.league.wk||wkStart(today());const L=leaguePts(wk),max=Math.max(1,...L.map(x=>x[1]));const d=document.createElement('div');d.className='display league';d.innerHTML=(`<button class="btn gold x" data-act="closeDisplay">✕ خروج</button><h1>🏆 دوري الفصول — ${esc(S.settings.school||'إتقان')}</h1><p style="font-size:1.4rem">أسبوع ${esc(hijS(wk))}</p>${L.map((x,i)=>`<div class="row ${i===0?'r1':''}"><span class="rk">${i<3?['🥇','🥈','🥉'][i]:AR(i+1)}</span><b style="min-width:30%">${esc(x[0])}</b><div class="bar"><i style="width:${100*x[1]/max}%"></i></div><b>${AR(x[1])}</b></div>`).join('')}<p style="text-align:center;margin-top:4vh;opacity:.8">© ١٤٤٨هـ عبدالله خالد العتيبي – جميع الحقوق محفوظة</p>`);femEl(d);document.body.appendChild(d);d.requestFullscreen&&d.requestFullscreen().catch(()=>{});DISP=setInterval(()=>{if(!document.body.contains(d))clearInterval(DISP)},5000)}
let DISP=null;function closeDisplay(){$$('.display').forEach(x=>x.remove());if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})}

/* ---------- passport ---------- */
V.passport=()=>{const L=studentNames();let st=VS.pass.st||L[0]||'';const sks=skillNames();const M=st?mastered(st):[];
 return head('🛂 جواز المهارات','جواز رقمي لكل طالب: ختم لكل مهارة يتقنها (≥ '+PC(TH().m)+').')+(L.length?`<div class="card no-print"><label class="f">الطالب<select id="passSt">${L.map(n=>`<option ${n===st?'selected':''}>${esc(n)}</option>`).join('')}</select></label></div>
 <div class="card" id="passDoc"><div class="acts" style="justify-content:space-between"><div><h3>🛂 جواز مهارات: ${esc(st)}</h3><p class="small muted">${esc(clsOf(st))} · ${esc(S.settings.school||'')} · ${AR(M.length)} من ${AR(sks.length)} مهارة متقنة</p></div><div class="acts no-print"><button class="btn sm" data-act="passHtml">📤 بطاقة لولي الأمر (HTML + QR)</button><button class="btn ghost sm" data-act="certFor" data-st="${esc(st)}" data-t="skill">🏅 شهادة</button></div></div>
 ${sks.length?`<div class="stamps">${sks.map(k=>{const m=mastery(st,k);return`<div class="stamp ${M.includes(k)?'':'off'}"><span style="font-size:1.6rem">${M.includes(k)?'✅':'⏳'}</span>${esc(k)}<small>${m==null?'لم يُقس':AR(m)+'٪'}</small></div>`}).join('')}</div>`:'<p class="muted">لا توجد مهارات بعد — أدخل نتائج في رادار الفاقد أو أضف مهارات.</p>'}</div>`:`<div class="card">${emptyAdd('students','أضف الطلاب أولاً ليظهر جواز كل طالب.')}</div>`)};
function passHtml(){const st=VS.pass.st||studentNames()[0];if(!st)return;const sks=skillNames(),M=mastered(st);const sum=`جواز مهارات ${st} — ${S.settings.school||''}\nالمهارات المتقنة (${M.length}/${sks.length}):\n${M.map(m=>'✓ '+m).join('\n')||'—'}\n${HF.format(new Date())}`;
 let qr='';try{const q=qrcode(0,'L');q.addData(fem(sum).slice(0,700));q.make();qr=q.createSvgTag({cellSize:3,margin:2,scalable:true})}catch(e){qr=''}
 const html=`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>جواز مهارات ${esc(st)}</title><style>body{font-family:Tajawal,Tahoma,sans-serif;background:#eef2f8;margin:0;padding:16px;color:#1b2433}.c{max-width:640px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 30px #0b1f3a33}.h{background:linear-gradient(to left,#0b1f3a,#1e4fa3,#0d9488);color:#fff;padding:20px;border-bottom:4px solid #e9c45c}.h h1{margin:0;font-size:1.4rem}.b{padding:18px}.s{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px}.t{border:3px double #c9a227;border-radius:50%;aspect-ratio:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;font-weight:800;color:#1e4fa3;padding:8px;font-size:.85rem}.o{opacity:.35;border-style:dashed}.q{text-align:center;margin-top:14px}.q svg{width:150px}.f{text-align:center;font-size:.75rem;color:#64748b;padding:10px}</style></head><body><div class="c"><div class="h"><h1>🛂 جواز المهارات</h1><div>${esc(st)} · ${esc(clsOf(st))}</div><div>${esc(S.settings.school||'')}</div></div><div class="b"><p>أتقن ${AR(M.length)} من ${AR(sks.length)} مهارة · ${esc(HF.format(new Date()))}</p><div class="s">${sks.map(k=>`<div class="t ${M.includes(k)?'':'o'}">${M.includes(k)?'✅':'⏳'}<br>${esc(k)}</div>`).join('')}</div><div class="q">${qr}<div style="font-size:.75rem">رمز QR يحوي ملخص الجواز نصياً</div></div></div><div class="f">© ١٤٤٨هـ عبدالله خالد العتيبي – جميع الحقوق محفوظة، يُمنع النسخ أو إعادة النشر دون إذن</div></div></body></html>`;
 const file=new File([fem(html)],`جواز-${st}.html`,{type:'text/html'});shareOrDownload(file,`جواز مهارات ${st}`,st)}

/* ---------- mirror ---------- */
let MT=null;
V.mirror=()=>{const r=S.reflections;const last=r.slice(-10);
 return head('🪞 مرآة المعلم','تأمل ذاتي خلال دقيقتين بعد الدرس + نسبة الفهم، مع ربطها باتجاه النتائج.')+
 `<div class="card"><h3>⏱️ تأمل سريع (دقيقتان) <span class="timer" id="mT" style="font-size:1.2rem">${MT?'':'٢:٠٠'}</span></h3><div class="fgrid">${['cls','subject','lesson','understood'].map(k=>fieldHtml(C.reflections.f.find(f=>f.k===k),'','m_')).join('')}${fieldHtml(C.reflections.f.find(f=>f.k==='good'),'','m_')}${fieldHtml(C.reflections.f.find(f=>f.k==='improve'),'','m_')}</div><div class="acts" style="margin-top:8px"><button class="btn" data-act="mSave">💾 حفظ التأمل</button><button class="btn ghost sm" data-act="mTimer">▶️ بدء المؤقت</button><span class="small muted">الفهم: كم طالباً من كل ١٠ أجاب سؤال الخروج صحيحاً؟ ×١٠</span></div></div>
 <div class="grid g2"><div class="card"><h3>📈 نسبة الفهم (أسبوعياً)</h3>${lineChart(trendBy(r,'understood'),{label:'الفهم'})}</div><div class="card"><h3>🔗 مقارنة مع نتائج الاختبارات القصيرة</h3>${lineChart(trendBy(S.results,'score'),{c:'#0d9488',label:'النتائج'})}<p class="small muted">${(()=>{const a=avg(r.map(x=>x.understood)),b=avg(S.results.map(x=>x.score));return a!=null&&b!=null?`متوسط الفهم المُقدَّر ${PC(a)} مقابل متوسط النتائج الفعلية ${PC(b)} — ${Math.abs(a-b)<10?'تقديرك قريب من الواقع 👌':a>b?'تقديرك أعلى من النتائج؛ جرّب أسئلة خروج أدق.':'نتائج طلابك أفضل من تقديرك 🌟'}`:'يظهر الربط عند توفر تأملات ونتائج.'})()}</p></div></div>`+tbl('reflections',{ta:1})};
function mSave(){const o=clean('reflections',{...readForm(document,C.reflections.f,'m_'),date:today()});if(o.understood==null){toast('أدخل نسبة الفهم');return}mut(()=>{ensureRefs(o,C.reflections.f);S.reflections.push({id:uid(),...o})},'✓ حُفظ التأمل');MT&&clearInterval(MT);MT=null}
function mTimer(){let end=Date.now()+120e3;clearInterval(MT);MT=setInterval(()=>{const e=$('#mT');const l=end-Date.now();if(!e||l<=0){clearInterval(MT);MT=null;if(e)e.textContent='انتهى الوقت ✓';return}e.textContent=fmtT(l)},500)}

/* ---------- visits lab ---------- */
const STD=[['r1','التخطيط للدرس',['تخطيط','اهداف','هدف','تمهيد','خطه']],['r2','إدارة الصف',['اداره','انضباط','وقت','هدوء','نظام']],['r3','التقويم',['تقويم','اسئله','سؤال','واجب','تغذيه']],['r4','تفاعل الطلاب',['تفاعل','مشاركه','نشاط','تعاوني','مجموعات']],['r5','التمايز ومراعاة الفروق',['فروق','تمايز','ضعاف','متفوقين','علاج']]];
const NEG=/(ضعف|ضعيف|قليل|(^|\s)(لم|لا|عدم)\s|يحتاج|تحتاج|غياب|بطء|قصور)/;
function feedback(v){const n=N(v.notes||'');const sents=n.split(/[.!؟\n،,]+|\s(?:و?لكن|بينما)\s|\sو(?=لم|ال|عدم)/).map(x=>x.trim()).filter(Boolean);const out=STD.map(([k,t,kw])=>{let r=v[k];const hits=sents.filter(s=>kw.some(w=>s.includes(w)));const neg=hits.some(s=>NEG.test(s));if(r==null&&hits.length)r=neg?2:3;return{k,t,r,neg,hits}});
 const str=out.filter(x=>x.r>=3),imp=out.filter(x=>x.r!=null&&x.r<=2);const PL={r1:'تصميم أهداف سلوكية قابلة للقياس وتمهيد محفز مرتبط بالحياة',r2:'توزيع زمن الحصة بمؤقت مرئي واعتماد قواعد صفية متفق عليها',r3:'استخدام بطاقات الخروج وأسئلة متدرجة مع تغذية راجعة فورية',r4:'توظيف التعلم التعاوني بأدوار محددة واستراتيجية فكّر-زاوج-شارك',r5:'إعداد مهام متمايزة بثلاثة مستويات ومجموعات مرنة حسب رادار الفاقد'};
 return{out,str,imp,plan:imp.map(x=>({t:x.t,a:PL[x.k],w:'خلال أسبوعين',ind:'ارتفاع التقدير في الزيارة القادمة إلى ٣ فأكثر'})),avg:avg(out.map(x=>x.r))}}
V.visits=()=>{const T=[...new Set(S.visits.map(v=>v.teacher))];const t=VS.vis.t||T[0]||'';const L=S.visits.filter(v=>v.teacher===t).sort((a,b)=>a.date<b.date?-1:1);
 return head('🔬 مختبر الزيارات الصفية','سجّل ملاحظاتك صوتياً ← تغذية راجعة منظمة وخطة تطوير، وتتبّع التحسن عبر الزيارات.')+tip('اضغط «🎤 إدخال صوتي» وصف الحصة بحرية (مثل: «التخطيط جيد والتمهيد مشوق، لكن التقويم ضعيف ولم تُراعَ الفروق»). سيُستخرج التقدير لكل معيار تلقائياً ويمكنك تعديله.')
 +tbl('visits',{extraH:'<th>المتوسط</th><th class="acts">التغذية الراجعة</th>',extra:v=>`<td>${AR(feedback(v).avg,1)}</td><td class="acts"><button class="btn sm" data-act="fb" data-id="${v.id}">📋 عرض</button></td>`})
 +(T.length?`<div class="card"><h3>📈 تتبّع التحسن: <select id="visT">${T.map(x=>`<option ${x===t?'selected':''}>${esc(x)}</option>`).join('')}</select></h3>${lineChart(L.map(v=>[hijS(v.date),(feedback(v).avg||0)*25]),{label:'التحسن'})}<p class="small muted">المحور: متوسط المعايير محوّلاً إلى ١٠٠ (٤ = ١٠٠٪). عدد الزيارات: ${AR(L.length)}${L.length>1?` · التغير: ${AR(((feedback(L.at(-1)).avg||0)-(feedback(L[0]).avg||0)),1)} درجة`:''}</p></div>`:'')};
function fbDlg(id){const v=S.visits.find(x=>x.id===id);const F=feedback(v);
 dlg(`<div id="fbDoc"><h3>📋 تغذية راجعة — ${esc(v.teacher)}</h3><p class="small">${esc(hij(v.date))} · ${esc(v.subject||'')} · ${esc(v.cls||'')}</p><div class="tw"><table><tr><th>المعيار</th><th>التقدير</th></tr>${F.out.map(x=>`<tr><td>${x.t}</td><td>${x.r==null?'—':'★'.repeat(Math.round(x.r))+'☆'.repeat(4-Math.round(x.r))}</td></tr>`).join('')}</table></div>
 <h3>✅ نقاط القوة</h3><ul>${F.str.map(x=>`<li>${x.t}</li>`).join('')||'<li class="muted">—</li>'}</ul><h3>🎯 فرص التحسين</h3><ul>${F.imp.map(x=>`<li>${x.t}</li>`).join('')||'<li class="muted">لا توجد</li>'}</ul>
 <h3>🗺️ خطة التطوير</h3>${F.plan.length?`<div class="tw"><table><tr><th>المجال</th><th>الإجراء</th><th>المدة</th><th>مؤشر التحقق</th></tr>${F.plan.map(p=>`<tr><td>${p.t}</td><td>${p.a}</td><td>${p.w}</td><td>${p.ind}</td></tr>`).join('')}</table></div>`:'<p>الاستمرار على الأداء المتميز وتوثيقه في مكتبة الممارسات.</p>'}${v.notes?`<h3>📝 الملاحظات</h3><p>${esc(v.notes)}</p>`:''}</div>
 <div class="dlg-acts"><button type="button" class="btn" data-act="docPdf" data-el="fbDoc" data-name="تغذية-راجعة-${esc(v.teacher)}">📄 PDF</button><button class="btn ghost" value="c">إغلاق</button></div>`)}

/* ---------- pact ---------- */
const HOME_ACT=['قراءة مشتركة لمدة ١٠ دقائق ثم سؤال الطالب عن الفكرة الرئيسة','حل ٣ مسائل قصيرة مع شرح الطالب لطريقته بصوت عالٍ','لعبة بطاقات سريعة لمراجعة المفردات أو الحقائق','ربط المهارة بموقف يومي في المنزل (تسوق، طبخ، قياس)'];
function weakest(st){return skillNames().map(k=>[k,mastery(st,k)]).filter(x=>x[1]!=null).sort((a,b)=>a[1]-b[1])[0]}
function waNum(m){m=normMob(m);return/^05\d{8}$/.test(m)?'966'+m.slice(1):''}
function pactMsg(p){const s=S.students.find(x=>x.name===p.student)||{};return`السلام عليكم ورحمة الله وبركاته\nولي أمر الطالب/ ${p.student}${s.parent?' (الأستاذ '+s.parent+')':''} المحترم\nضمن ميثاق الشراكة بين المدرسة والأسرة لهذا الأسبوع (${hij(p.week)}):\n🎯 الهدف: ${p.goal}\n🏠 نشاط منزلي (١٠ دقائق يومياً): ${p.activity||'—'}\nشاكرين تعاونكم ودعمكم.\n${S.settings.school||''}${S.settings.user.name?'\n'+S.settings.user.name:''}`}
V.pact=()=>head('🤝 ميثاق ولي الأمر','هدف أسبوعي + نشاط منزلي ١٠ دقائق لكل طالب، ورسالة واتساب جاهزة (أنت من يضغط إرسال).',`<button class="btn gold sm" data-act="pactClass">✨ إنشاء مواثيق لفصل من أضعف المهارات</button>`)+tip('زر واتساب يفتح المحادثة برسالة معبأة مسبقاً فقط — لا يُرسل شيء تلقائياً. يلزم جوال ولي الأمر في قائمة الطلاب.')
 +tbl('pacts',{ta:1,extraH:'<th class="acts">واتساب</th>',extra:p=>{const s=S.students.find(x=>x.name===p.student)||{};const n=waNum(s.mobile);const sent=S.sent.some(x=>x.ref===p.id);return`<td class="acts">${n?`<a class="btn green sm" href="https://wa.me/${n}?text=${encodeURIComponent(fem(pactMsg(p)))}" target="_blank" rel="noopener" data-act="logSent" data-ref="${p.id}" data-st="${esc(p.student)}" data-kind="ميثاق">${WAICON} فتح واتساب</a>`:'<span class="muted small">لا يوجد جوال</span>'} ${sent?'<span class="tag ok">أُرسل ✓</span>':''}</td>`}});
function pactClass(){dlg(`<h3>✨ إنشاء مواثيق لفصل</h3><div class="fgrid"><label class="f">الفصل${clsSel('pcCls','')}</label></div><p class="small muted">سيُنشأ لكل طالب هدف من أضعف مهارة لديه ونشاط منزلي مقترح، ويمكنك تعديل أي ميثاق بعدها.</p><div class="dlg-acts"><button type="button" class="btn" data-act="pactClassGo">إنشاء</button><button class="btn ghost" value="c">إلغاء</button></div>`)}
function pactClassGo(){const c=$('#pcCls').value;const L=studentNames(c);if(!L.length){toast('لا يوجد طلاب');return}const wk=wkStart(today());closeDlg();mut(()=>{L.forEach((st,i)=>{if(S.pacts.some(p=>p.student===st&&p.week===wk))return;const w=weakest(st);S.pacts.push({id:uid(),student:st,week:wk,goal:w?'تحسين مهارة «'+w[0]+'»':'المحافظة على المستوى والمراجعة اليومية',activity:fem(HOME_ACT[i%HOME_ACT.length])})})},'✓ أُنشئت المواثيق')}

/* ---------- ops ---------- */
V.ops=()=>{const T=S.tests.slice().sort((a,b)=>a.date<b.date?-1:1);const up=T.filter(t=>daysTo(t.date)>=0);const nx=up[0];const R=readiness(nx&&nx.subject);
 let plan='';if(nx&&R.weak.length){const d=Math.max(1,Math.min(daysTo(nx.date),30));const w=R.weak.filter(x=>x.m<TH().m);const L=w.length?w:R.weak;const rows=[];for(let i=0;i<d;i++){const dt=new Date();dt.setDate(dt.getDate()+i);if(dt.getDay()===5||dt.getDay()===6)continue;rows.push([HF.format(dt),L[i%L.length]])}
  plan=`<div class="card"><h3>📅 خطة المراجعة اليومية حتى ${esc(nx.name)}</h3><div class="tw"><table><tr><th>اليوم</th><th>المهارة</th><th>المتوسط</th><th>نشاط مقترح (١٠–١٥ دقيقة)</th></tr>${rows.slice(0,20).map((r,i)=>`<tr><td>${r[0]}</td><td>${esc(r[1].sk)}</td><td>${PC(r[1].m)}</td><td>${esc((r[1].m<60?ACTV.low:ACTV.mid)[i%3])}</td></tr>`).join('')}</table></div></div>`}
 return head('⏳ غرفة عمليات الاختبارات','عدّ تنازلي للاختبارات الوطنية (تحددها بنفسك)، ومؤشر جاهزية، وخطة مراجعة من أضعف المهارات.')
 +`<div class="grid g3">${up.slice(0,3).map(t=>`<div class="kpi"><b>${AR(daysTo(t.date))} يوم</b><span>${esc(t.name)} · ${esc(hij(t.date))}</span></div>`).join('')||`<div class="kpi"><b>—</b><span>لم تُحدَّد مواعيد بعد</span></div>`}</div>
 <div class="grid g2" style="margin-top:14px"><div class="card"><h3>🎯 مؤشر الجاهزية ${nx&&nx.subject?'('+esc(nx.subject)+')':''}</h3><div class="gauge">${gauge(R.v==null?null:Math.round(R.v),'متوسط إتقان المهارات')}</div></div><div class="card"><h3>⚠️ أضعف المهارات</h3>${barChart(R.weak.slice(0,6).map(x=>[x.sk,x.m]),{col:heatCol})}</div></div>`+plan+tbl('tests')};

/* ---------- practices ---------- */
V.practices=()=>{const now=hMonth(today());const M=S.practices.filter(p=>hMonth(p.date)===now&&p.before!=null&&p.after!=null).sort((a,b)=>(b.after-b.before)-(a.after-a.before));const best=M[0];
 return head('🌟 مكتبة الممارسات المتميزة','وثّق الممارسات مع أرقام قبل/بعد، وتُمنح شارة أفضل ممارسة شهرياً تلقائياً.')+(best?`<div class="hero"><h2>🏅 شارة أفضل ممارسة لهذا الشهر</h2><p class="gold" style="font-size:1.2rem">${esc(best.title)} — ${esc(best.teacher||'')}</p><p>من ${PC(best.before)} إلى ${PC(best.after)} (تحسن ${AR(best.after-best.before)} نقطة)</p></div>`:'')
 +tbl('practices',{extraH:'<th>الأثر</th>',extra:p=>`<td>${p.before!=null&&p.after!=null?`<span class="tag ${p.after>=p.before?'ok':'bad'}">${p.after>=p.before?'▲':'▼'} ${AR(Math.abs(p.after-p.before))}</span>`:'—'}</td>`})};

/* ---------- PDF / share ---------- */
function loadScript(src){return new Promise((ok,no)=>{if(src.includes('jspdf')&&window.jspdf||src.includes('html2canvas')&&window.html2canvas)return ok();const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=()=>no(new Error('تعذّر تحميل '+src));document.head.appendChild(s)})}
async function renderDoc(html,land){await loadScript('vendor/html2canvas.min.js');await loadScript('vendor/jspdf.umd.min.js');const W=land?1123:794;const box=document.createElement('div');box.style.cssText=`position:fixed;top:0;left:-20000px;width:${W}px;background:#fff;color:#111;direction:rtl;font-family:Tajawal,sans-serif`;box.innerHTML=fem(html);document.body.appendChild(box);
 try{await document.fonts.ready;await Promise.all($$('img',box).map(i=>i.complete?1:new Promise(r=>{i.onload=i.onerror=r})));const cv=await html2canvas(box,{scale:2,backgroundColor:'#fff',useCORS:true,logging:false});const{jsPDF}=window.jspdf;const pdf=new jsPDF({orientation:land?'l':'p',unit:'pt',format:'a4'});
  const pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight();const ih=cv.height*pw/cv.width;if(land||ih<=ph+2)pdf.addImage(cv.toDataURL('image/jpeg',.93),'JPEG',0,0,pw,Math.min(ih,ph));else{const sliceH=Math.floor(cv.width*ph/pw);for(let y=0,p=0;y<cv.height;y+=sliceH,p++){const c=document.createElement('canvas');c.width=cv.width;c.height=Math.min(sliceH,cv.height-y);c.getContext('2d').drawImage(cv,0,-y);if(p)pdf.addPage();pdf.addImage(c.toDataURL('image/jpeg',.93),'JPEG',0,0,pw,c.height*pw/cv.width)}}
  return{pdf:pdf.output('blob'),canvas:cv}}finally{box.remove()}}
